// Some portions generated by Claude
/**
 * The compact form of a stored graph (format 2). A graph of 50,000 nodes and 200,000 edges took 120 MB as plain JSON:
 * every edge repeated its id (its three terms), its predicate's label and its batch. Here nodes, predicates, types and
 * batches are tables; an edge is four numbers; ids and labels that can be derived again are left out. Decoding gives
 * the plain form back, which parseWorkspacePayload then validates as before.
 */
import { tripleEdgeId } from "./graph-terms.ts";
import { INTERNAL_BNODE_NODE_PREFIX, sparqlNodeId, type SparqlTerm } from "./rdf-terms.ts";
import type { WorkspaceGraphEdge, WorkspaceGraphNode, WorkspacePayload } from "./workspace.ts";

export const WORKSPACE_FORMAT = 2;

const KIND = ["iri", "literal", "blank"] as const;

/** The id a node would get from its value; nodes whose id is exactly that store none. */
function derivedId(node: Pick<WorkspaceGraphNode, "kind" | "termValue" | "datatype" | "language">) {
  if (node.kind === "blank") return node.termValue === undefined ? null : `${INTERNAL_BNODE_NODE_PREFIX}${node.termValue}`;
  if (node.kind !== "literal" || node.termValue === undefined) return null;
  const term: SparqlTerm = { type: "literal", value: node.termValue };
  if (node.datatype) term.datatype = node.datatype;
  if (node.language) term["xml:lang"] = node.language;
  return sparqlNodeId(term);
}

const round = (value: number) => Math.round(value * 100) / 100;

/**
 * The last graph encoded and its JSON members. Moving the view or selecting saves again with the same graph object
 * (graphs are never changed in place), which at 50,000 nodes took 200 ms each time; only the last one is kept, so
 * the graphs held by undo history do not keep their text alive.
 */
let lastEncoded: { graph: WorkspacePayload["graph"]; members: string } | null = null;

/** The payload in the compact form, as JSON text. */
export function encodeWorkspace(payload: WorkspacePayload): string {
  const { graph, ...rest } = payload;
  if (lastEncoded?.graph !== graph) lastEncoded = { graph, members: encodeGraphMembers(graph) };
  const head = JSON.stringify({ version: WORKSPACE_FORMAT, ...rest });
  return `${head.slice(0, -1)},${lastEncoded.members}}`;
}

/** The graph's members of the compact form (`"revision":…,"types":…`), without the braces. */
function encodeGraphMembers(graph: WorkspacePayload["graph"]) {
  const types: Array<[string, string]> = [];
  const typeIndex = new Map<string, number>();
  const nodeIndex = new Map<string, number>();
  const nodes = graph.nodes.map((node, index) => {
    nodeIndex.set(node.id, index);
    const derived = derivedId(node);
    const tuple: unknown[] = [
      node.kind === "iri" || derived !== node.id ? node.id : 0,
      node.label,
      KIND.indexOf(node.kind),
      node.x === undefined ? null : round(node.x),
      node.y === undefined ? null : round(node.y),
      node.pinned === undefined ? null : node.pinned ? 1 : 0,
      node.termValue === undefined ? null : node.kind === "iri" && node.termValue === node.id ? 0 : node.termValue,
      node.datatype ?? null,
      node.language ?? null,
      node.types === undefined
        ? null
        : node.types.map((type) => {
            const key = `${type.id}\u0000${type.label}`;
            let at = typeIndex.get(key);
            if (at === undefined) {
              at = types.length;
              typeIndex.set(key, at);
              types.push([type.id, type.label]);
            }
            return at;
          }),
    ];
    while (tuple.length > 3 && tuple[tuple.length - 1] === null) tuple.pop();
    return tuple;
  });
  const predicates: Array<[string, string]> = [];
  const predicateIndex = new Map<string, number>();
  const batchIds: string[] = [];
  const batchIndex = new Map<string, number>();
  const edges: number[] = [];
  const edgeIds: Record<number, string> = {};
  const edgeLabels: Record<number, string> = {};
  graph.edges.forEach((edge, index) => {
    let predicate = predicateIndex.get(edge.predicate);
    if (predicate === undefined) {
      predicate = predicates.length;
      predicateIndex.set(edge.predicate, predicate);
      predicates.push([edge.predicate, edge.label]);
    }
    let batch = -1;
    if (edge.batchId !== undefined) {
      batch = batchIndex.get(edge.batchId) ?? -1;
      if (batch < 0) {
        batch = batchIds.length;
        batchIndex.set(edge.batchId, batch);
        batchIds.push(edge.batchId);
      }
    }
    edges.push(nodeIndex.get(edge.source) ?? -1, predicate, nodeIndex.get(edge.target) ?? -1, batch);
    if (edge.id !== tripleEdgeId(edge.source, edge.predicate, edge.target)) edgeIds[index] = edge.id;
    if (edge.label !== predicates[predicate][1]) edgeLabels[index] = edge.label;
  });
  return JSON.stringify({
    revision: graph.revision,
    types,
    nodes,
    predicates,
    batchIds,
    edges,
    edgeIds,
    edgeLabels,
    ...(graph.statementLinks ? { statementLinks: graph.statementLinks } : {}),
  }).slice(1, -1);
}

const isIndex = (value: unknown, length: number) => Number.isInteger(value) && (value as number) >= 0 && (value as number) < length;
const optionalString = (value: unknown) => (typeof value === "string" ? value : undefined);

/**
 * The plain form of a compact payload, unvalidated; null when it is not one or its structure is broken (an index out
 * of range, a field of the wrong kind).
 */
export function decodeWorkspace(parsed: unknown): Record<string, unknown> | null {
  const data = parsed as Record<string, unknown> | null;
  if (!data || typeof data !== "object" || data.version !== WORKSPACE_FORMAT) return null;
  const { types, nodes, predicates, batchIds, edges, edgeIds, edgeLabels, revision, statementLinks, version: _version, ...rest } = data;
  if (![types, nodes, predicates, batchIds, edges].every(Array.isArray)) return null;
  const typeTable = types as unknown[];
  const nodeTuples = nodes as unknown[];
  const predicateTable = predicates as unknown[];
  const batchTable = batchIds as unknown[];
  const edgeNumbers = edges as unknown[];
  const ids = (edgeIds ?? {}) as Record<string, unknown>;
  const labels = (edgeLabels ?? {}) as Record<string, unknown>;
  if (typeof ids !== "object" || typeof labels !== "object" || edgeNumbers.length % 4) return null;

  const plainNodes: WorkspaceGraphNode[] = [];
  for (const tuple of nodeTuples) {
    if (!Array.isArray(tuple) || tuple.length < 3 || !isIndex(tuple[2], KIND.length)) return null;
    const [id, label, kind, x, y, pinned, termValue, datatype, language, nodeTypes] = tuple;
    const node: WorkspaceGraphNode = { id: "", label: label as string, kind: KIND[kind as number] };
    if (typeof termValue === "string") node.termValue = termValue;
    else if (termValue === 0 && typeof id === "string") node.termValue = id;
    if (typeof datatype === "string") node.datatype = datatype;
    if (typeof language === "string") node.language = language;
    const resolvedId = id === 0 ? derivedId(node) : id;
    if (typeof resolvedId !== "string") return null;
    node.id = resolvedId;
    if (typeof x === "number") node.x = x;
    if (typeof y === "number") node.y = y;
    if (pinned === 0 || pinned === 1) node.pinned = pinned === 1;
    if (Array.isArray(nodeTypes)) {
      if (!nodeTypes.every((at) => isIndex(at, typeTable.length))) return null;
      node.types = nodeTypes.map((at) => {
        const type = typeTable[at as number];
        if (!Array.isArray(type)) return { id: "", label: "" };
        return { id: type[0] as string, label: type[1] as string };
      });
    }
    plainNodes.push(node);
  }
  const plainEdges: WorkspaceGraphEdge[] = [];
  for (let at = 0; at < edgeNumbers.length; at += 4) {
    const [source, predicate, target, batch] = edgeNumbers.slice(at, at + 4);
    if (!isIndex(source, plainNodes.length) || !isIndex(target, plainNodes.length) || !isIndex(predicate, predicateTable.length))
      return null;
    if (batch !== -1 && !isIndex(batch, batchTable.length)) return null;
    const entry = predicateTable[predicate as number];
    if (!Array.isArray(entry) || typeof entry[0] !== "string") return null;
    const index = at / 4;
    const sourceId = plainNodes[source as number].id;
    const targetId = plainNodes[target as number].id;
    const edge: WorkspaceGraphEdge = {
      id: optionalString(ids[index]) ?? tripleEdgeId(sourceId, entry[0], targetId),
      source: sourceId,
      predicate: entry[0],
      label: optionalString(labels[index]) ?? (entry[1] as string),
      target: targetId,
    };
    if (batch !== -1) edge.batchId = batchTable[batch as number] as string;
    plainEdges.push(edge);
  }
  return {
    ...rest,
    graph: { nodes: plainNodes, edges: plainEdges, revision, ...(statementLinks ? { statementLinks } : {}) },
  };
}
